"""CuTe MoE kernel dispatch via AOT-emitted host wrappers.

Public routed-GEMM entries are up/down × bf16/fp8. `invoke_cute_moe`
is the full-layer entry for non-routed MoE kernels. Each variant ships
as a self-contained `.so` that bundles the cute-compiled launch logic —
grid derivation, smem optin, cluster dims, warpgroup register
reallocation, PDL stream serialization. Dispatch resolves the `.so`,
builds memref structs from torch tensors in the wrapper's argument
order, and invokes the exported `ciface` entry.

When `KESTREL_CUTE_JIT=1` is set, missing variants are compiled on
demand (source install only).
"""

# PEP 563: keep annotations as strings so type-only references (e.g.
# `torch.Tensor` in the signatures below) don't get evaluated at import
# time. Lets tests that fake `sys.modules['torch']` with a stub module
# (see tests/test_cubin_bundles_launch_config.py) transitively import
# this file without tripping AttributeError on torch.Tensor.
from __future__ import annotations

import torch

from kestrel_kernels.arch import get_cuda_arch, sm_arch_at_least
from kestrel_kernels.cute_aot_runtime import AotFamily, get_raw_stream
from kestrel_kernels.cute_moe.config import (
    CuteMoeConfig,
    MoeVariant,
    WarpGemvVariant,
    get_cute_moe_routed_config,
    is_block_scheduled_fp8_kernel,
)
from kestrel_kernels.fallback import ceil_div, is_cute_jit_enabled


_CUTE_TOP_K_UP_DECODE = 8


def _jit_compile_fn_factory(variant: MoeVariant):
    """Produce a cute `compile_fn(arch)` for a single MoE variant."""
    from scripts.precompile import cubin_bundles as _cubin_bundles
    return _cubin_bundles._compile_cute_moe(variant)


def _warpgemv_jit_compile_fn_factory(variant):
    def compile_fn(arch: str):
        from kestrel_kernels.cute_moe.warp_gemv_kernel import (
            make_compile_args,
        )

        return make_compile_args(variant, arch)

    return compile_fn


_family = AotFamily(
    "cute_moe",
    jit_compile_fn=_jit_compile_fn_factory if is_cute_jit_enabled() else None,
)
_warpgemv_family = AotFamily(
    "cute_moe_warpgemv",
    jit_compile_fn=(
        _warpgemv_jit_compile_fn_factory if is_cute_jit_enabled() else None
    ),
)


def _variant_for_config(
    kind: str,
    config: CuteMoeConfig,
    N: int,
    K: int,
    use_pdl: bool,
    compact_schedule: bool = False,
    weight_scale_layout: str = "channel",
) -> MoeVariant:
    return MoeVariant(
        kind=kind,
        block_m=config.block_m, block_n=config.block_n, block_k=config.block_k,
        num_warps=config.num_warps, num_stages=config.num_stages,
        N=N, K=K, dtype=config.dtype,
        kernel_type=config.kernel_type,
        compact_schedule=compact_schedule,
        use_pdl=use_pdl,
        cluster_M=config.cluster_M,
        weight_scale_layout=weight_scale_layout,
    )


def _shrink_routing_for_em_launch(
    config: CuteMoeConfig, top_k: int, num_valid_tokens: int,
    sorted_token_ids: torch.Tensor, expert_ids: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Avoid launching M-blocks that would exit due to routing padding.

    Matches the Triton MoE reference: cap the M-block grid at
    num_valid_tokens * block_m, which is an upper bound on post-padded M.
    """
    em_full = int(sorted_token_ids.numel())
    em_launch = min(em_full, num_valid_tokens * int(config.block_m))
    if em_launch < em_full:
        sorted_token_ids = sorted_token_ids[:em_launch]
        m_blocks = ceil_div(em_launch, int(config.block_m))
        expert_ids = expert_ids[:m_blocks]
    return sorted_token_ids, expert_ids


def _require_routed_config(config: CuteMoeConfig) -> None:
    if config.kernel_type == "warpgemv":
        raise ValueError("warpgemv is a full-layer MoE kernel; use invoke_cute_moe")
    if config.kernel_type == "tcgen":
        raise ValueError("tcgen MoE uses invoke_cute_moe_*_fp8_tcgen")


def _require_bf16_warp_full_n(config: CuteMoeConfig, n: int) -> None:
    # Tried BF16 warp block_n=256 for Gemma's N=1408 up projection: the first
    # production launch deterministically returned CUDA_ERROR_ILLEGAL_ADDRESS
    # on B200; keeping BF16 warp output tiles exact until its N tail is fixed.
    if config.dtype == "bf16" and config.kernel_type == "warp":
        if int(n) % int(config.block_n) != 0:
            raise ValueError("BF16 warp output N must be divisible by block_n")


def _require_tcgen_config(config: CuteMoeConfig) -> None:
    if config.kernel_type != "tcgen":
        raise ValueError("tcgen invoke requires kernel_type='tcgen'")


def _require_mxfp4_tcgen_config(config: CuteMoeConfig) -> None:
    if config.kernel_type != "tcgen" or config.dtype != "mxfp4":
        raise ValueError("MXFP4 tcgen invoke requires kernel_type='tcgen' and dtype='mxfp4'")


def _require_mxfp4_warp_config(config: CuteMoeConfig) -> None:
    if config.kernel_type != "warp" or config.dtype != "mxfp4":
        raise ValueError("MXFP4 warp invoke requires kernel_type='warp' and dtype='mxfp4'")


def _require_compact_fp8_config(config: CuteMoeConfig) -> CuteMoeConfig:
    if (
        not is_block_scheduled_fp8_kernel(config.kernel_type)
        or config.dtype != "fp8"
    ):
        raise ValueError(
            "compact FP8 invoke requires kernel_type='warp', 'qmma', or 'wgmma' "
            "and dtype='fp8'"
        )
    return config


def _mxfp4_storage_as_uint8(tensor: torch.Tensor, name: str) -> torch.Tensor:
    fp4_dtype = getattr(torch, "float4_e2m1fn_x2", None)
    if fp4_dtype is not None and tensor.dtype == fp4_dtype:
        return tensor.view(torch.uint8)
    if tensor.dtype == torch.uint8:
        return tensor
    if tensor.dtype == torch.int8:
        return tensor.view(torch.uint8)
    raise ValueError(f"{name} must be torch.float4_e2m1fn_x2 or byte storage")


def _e8m0_storage_as_uint8(tensor: torch.Tensor, name: str) -> torch.Tensor:
    e8m0_dtype = getattr(torch, "float8_e8m0fnu", None)
    if e8m0_dtype is not None and tensor.dtype == e8m0_dtype:
        return tensor.view(torch.uint8)
    if tensor.dtype == torch.uint8:
        return tensor
    raise ValueError(f"{name} must be torch.float8_e8m0fnu or uint8 storage")


def _validate_fp8_scale_layout(weight_scale_layout: str) -> str:
    if weight_scale_layout not in ("channel", "block128", "block128_interleaved8"):
        raise ValueError(
            f"unsupported FP8 weight scale layout: {weight_scale_layout!r}"
        )
    return weight_scale_layout


def _validate_fp8_weight_scale_shape(
    scale: torch.Tensor,
    *,
    name: str,
    num_experts: int,
    n: int,
    k: int,
    weight_scale_layout: str,
) -> None:
    if weight_scale_layout == "channel":
        if tuple(scale.shape) != (num_experts, n):
            raise ValueError(f"{name} must have shape [experts, N]")
        return
    if weight_scale_layout == "block128":
        if tuple(scale.shape) != (
            num_experts,
            ceil_div(n, 128),
            ceil_div(k, 128),
        ):
            raise ValueError(
                f"{name} must have shape [experts, ceil(N / 128), ceil(K / 128)]"
            )
        return
    if n % 2 != 0:
        raise ValueError("block128_interleaved8 requires even output dimension")
    if tuple(scale.shape) != (
        num_experts,
        2,
        ceil_div(n // 2, 128),
        ceil_div(k, 128),
    ):
        raise ValueError(
            f"{name} must have shape "
            "[experts, 2, ceil((N / 2) / 128), ceil(K / 128)]"
        )


def _resolve_aot_bundle(family: AotFamily, variant):
    """family.resolve + the no-variant error, hoisted so per-impl callers
    can resolve once instead of per call (MoeVariant.variant_key alone is
    an f-string build per access)."""
    arch = get_cuda_arch()
    bundle = family.resolve(variant, arch)
    if bundle is None:
        raise RuntimeError(
            f"No {family.family_name} AOT variant for {variant.variant_key} on arch={arch}. "
            "The installed kestrel-kernels wheel does not include this "
            "precompiled kernel; upgrade or reinstall kestrel-kernels, or "
            "report the missing variant."
        )
    return bundle


_VARIANT_BUNDLE_MEMO: dict = {}


def _variant_and_bundle(
    kind: str,
    config: CuteMoeConfig,
    N: int,
    K: int,
    use_pdl: bool,
    compact_schedule: bool = False,
    weight_scale_layout: str = "channel",
    family: "AotFamily | None" = None,
):
    """Memoized `_variant_for_config` + `_resolve_aot_bundle`.

    The variant dataclass build and its `variant_key` f-string cost ~2µs
    per call; the MoE forward pays it twice per layer. CuteMoeConfig is
    frozen/hashable, so the whole resolution is keyed directly on it.
    """
    fam = family if family is not None else _family
    key = (
        id(fam),
        config,
        kind,
        N,
        K,
        use_pdl,
        compact_schedule,
        weight_scale_layout,
    )
    hit = _VARIANT_BUNDLE_MEMO.get(key)
    if hit is not None:
        return hit
    variant = _variant_for_config(
        kind, config, N, K, use_pdl=use_pdl, compact_schedule=compact_schedule,
        weight_scale_layout=weight_scale_layout,
    )
    bundle = _resolve_aot_bundle(fam, variant)
    hit = (variant, bundle)
    _VARIANT_BUNDLE_MEMO[key] = hit
    return hit


def _invoke_aot(
    family: AotFamily,
    variant,
    tensors: list[torch.Tensor],
    first_tensor: torch.Tensor | None = None,
    bundle=None,
) -> None:
    if bundle is None:
        bundle = _resolve_aot_bundle(family, variant)

    if first_tensor is None:
        first_tensor = tensors[0]
    device_index = int(first_tensor.device.index or 0)
    bundle.aot._ensure_device(device_index)
    bundle.invoke_state().invoke(tensors, get_raw_stream(device_index))


def _invoke_cute_moe_warpgemv(
    x: torch.Tensor,
    topk_ids: torch.Tensor,
    topk_weights: torch.Tensor,
    up_weight: torch.Tensor,
    up_scale: torch.Tensor,
    down_weight: torch.Tensor,
    down_scale: torch.Tensor,
    *,
    out: torch.Tensor | None,
    activation_scratch: torch.Tensor | None,
    warps_per_block: int,
    weight_dtype: str = "fp8",
    weight_scale_layout: str = "channel",
    activation: str = "gelu",
) -> torch.Tensor:
    if x.device.type != "cuda":
        raise ValueError("warp-gemv MoE requires CUDA tensors")
    if x.dtype != torch.bfloat16 or x.ndim != 2:
        raise ValueError("x must be a BF16 CUDA tensor with shape [tokens, hidden]")
    if topk_ids.dtype != torch.int32 or topk_ids.ndim != 2:
        raise ValueError("topk_ids must be int32 with shape [tokens, top_k]")
    if topk_weights.shape != topk_ids.shape:
        raise ValueError("topk_weights must have the same shape as topk_ids")
    if topk_weights.dtype not in (torch.bfloat16, torch.float32):
        raise ValueError("warp-gemv MoE expects BF16 or FP32 topk_weights")
    if weight_dtype == "mxfp4":
        up_weight = _mxfp4_storage_as_uint8(up_weight, "up_weight")
        down_weight = _mxfp4_storage_as_uint8(down_weight, "down_weight")
        up_scale = _e8m0_storage_as_uint8(up_scale, "up_scale")
        down_scale = _e8m0_storage_as_uint8(down_scale, "down_scale")
    elif weight_dtype == "fp8":
        weight_scale_layout = _validate_fp8_scale_layout(weight_scale_layout)
        if up_weight.dtype != torch.uint8 or down_weight.dtype != torch.uint8:
            raise ValueError("warp-gemv MoE expects FP8 expert weights as uint8")
        if up_scale.dtype != torch.float32 or down_scale.dtype != torch.float32:
            raise ValueError("warp-gemv MoE expects fp32 expert scales")
    elif weight_dtype == "bf16":
        if up_weight.dtype != torch.bfloat16 or down_weight.dtype != torch.bfloat16:
            raise ValueError("warp-gemv BF16 MoE expects BF16 expert weights")
        if up_scale.dtype != torch.bfloat16 or down_scale.dtype != torch.bfloat16:
            raise ValueError("warp-gemv BF16 ABI placeholders must be BF16 tensors")
        if up_scale.numel() != 1 or down_scale.numel() != 1:
            raise ValueError("warp-gemv BF16 ABI placeholders must have one element")
    else:
        raise ValueError(f"unsupported warp-gemv weight dtype: {weight_dtype!r}")
    if not (
        x.is_contiguous()
        and topk_ids.is_contiguous()
        and topk_weights.is_contiguous()
        and up_weight.is_contiguous()
        and up_scale.is_contiguous()
        and down_weight.is_contiguous()
        and down_scale.is_contiguous()
    ):
        raise ValueError("warp-gemv MoE inputs must be contiguous")

    tokens, hidden = map(int, x.shape)
    if int(topk_ids.shape[0]) != tokens:
        raise ValueError("topk_ids token dimension must match x")
    top_k = int(topk_ids.shape[1])
    if top_k <= 0:
        raise ValueError("warp-gemv MoE requires top_k > 0")
    num_experts, up_n, up_k = map(int, up_weight.shape)
    if weight_dtype == "mxfp4":
        if up_k * 2 != hidden or up_n % 2 != 0:
            raise ValueError(
                "MXFP4 up_weight must have shape "
                "[experts, 2 * intermediate, hidden / 2]"
            )
    elif up_k != hidden or up_n % 2 != 0:
        raise ValueError("up_weight must have shape [experts, 2 * intermediate, hidden]")
    intermediate = up_n // 2
    if hidden % 16 != 0 or intermediate % 16 != 0:
        raise ValueError("warp-gemv MoE requires hidden/intermediate multiples of 16")
    if weight_dtype == "mxfp4":
        if tuple(up_scale.shape) != (
            num_experts,
            ceil_div(up_n, 128),
            ceil_div(hidden, 128),
            512,
        ):
            raise ValueError(
                "MXFP4 up_scale must have shape "
                "[experts, ceil(2 * intermediate / 128), ceil(hidden / 128), 512]"
            )
        if tuple(down_weight.shape) != (num_experts, hidden, intermediate // 2):
            raise ValueError(
                "MXFP4 down_weight must have shape "
                "[experts, hidden, intermediate / 2]"
            )
        if tuple(down_scale.shape) != (
            num_experts,
            ceil_div(hidden, 128),
            ceil_div(intermediate, 128),
            512,
        ):
            raise ValueError(
                "MXFP4 down_scale must have shape "
                "[experts, ceil(hidden / 128), ceil(intermediate / 128), 512]"
            )
    elif weight_dtype == "fp8":
        if tuple(up_scale.shape) != (num_experts, up_n):
            if weight_scale_layout == "channel":
                raise ValueError("up_scale must have shape [experts, 2 * intermediate]")
        if tuple(down_weight.shape) != (num_experts, hidden, intermediate):
            raise ValueError("down_weight must have shape [experts, hidden, intermediate]")
        _validate_fp8_weight_scale_shape(
            up_scale,
            name="up_scale",
            num_experts=num_experts,
            n=up_n,
            k=hidden,
            weight_scale_layout=weight_scale_layout,
        )
        down_scale_layout = (
            "block128"
            if weight_scale_layout == "block128_interleaved8"
            else weight_scale_layout
        )
        _validate_fp8_weight_scale_shape(
            down_scale,
            name="down_scale",
            num_experts=num_experts,
            n=hidden,
            k=intermediate,
            weight_scale_layout=down_scale_layout,
        )
    else:
        if tuple(down_weight.shape) != (num_experts, hidden, intermediate):
            raise ValueError("down_weight must have shape [experts, hidden, intermediate]")

    if out is None:
        out = torch.empty((tokens, hidden), device=x.device, dtype=x.dtype)
    elif (
        tuple(out.shape) != (tokens, hidden)
        or out.device != x.device
        or out.dtype != x.dtype
        or not out.is_contiguous()
    ):
        raise ValueError("out must be contiguous BF16 with shape [tokens, hidden]")

    if activation_scratch is None:
        activation_tensor = torch.empty(
            (tokens * top_k, intermediate), device=x.device, dtype=x.dtype
        )
    else:
        activation_tensor = activation_scratch
        if (
            tuple(activation_tensor.shape) != (tokens * top_k, intermediate)
            or activation_tensor.device != x.device
            or activation_tensor.dtype != x.dtype
            or not activation_tensor.is_contiguous()
        ):
            raise ValueError(
                "activation_scratch must be contiguous BF16 with shape "
                "[tokens * top_k, intermediate]"
            )

    warps_per_block = int(warps_per_block)
    if warps_per_block <= 0:
        raise ValueError("warps_per_block must be positive")

    gate_variant = WarpGemvVariant(
        kind="gate",
        hidden_size=hidden,
        intermediate_size=intermediate,
        top_k=top_k,
        dtype=weight_dtype,
        warps_per_block=warps_per_block,
        weight_scale_layout=weight_scale_layout,
        activation=activation,
    )
    down_variant = WarpGemvVariant(
        kind="down",
        hidden_size=hidden,
        intermediate_size=intermediate,
        top_k=top_k,
        dtype=weight_dtype,
        warps_per_block=warps_per_block,
        weight_scale_layout=(
            "block128"
            if weight_scale_layout == "block128_interleaved8"
            else weight_scale_layout
        ),
        topk_weight_dtype=(
            "fp32" if topk_weights.dtype == torch.float32 else "bf16"
        ),
    )
    _invoke_aot(
        _warpgemv_family,
        gate_variant,
        [
            x,
            topk_ids,
            up_weight,
            up_scale,
            activation_tensor,
        ],
    )
    _invoke_aot(
        _warpgemv_family,
        down_variant,
        [
            activation_tensor,
            topk_ids,
            topk_weights,
            down_weight,
            down_scale,
            out,
        ],
    )
    return out


def _invoke_cute_moe_warpgemv_up_fp8(
    x: torch.Tensor,
    topk_ids: torch.Tensor,
    up_weight: torch.Tensor,
    up_scale: torch.Tensor,
    out: torch.Tensor,
    *,
    warps_per_block: int,
    weight_scale_layout: str = "channel",
) -> None:
    hidden = int(x.shape[1])
    top_k = int(topk_ids.shape[1])
    intermediate = int(up_weight.shape[1]) // 2
    weight_scale_layout = _validate_fp8_scale_layout(weight_scale_layout)
    _validate_fp8_weight_scale_shape(
        up_scale,
        name="up_scale",
        num_experts=int(up_weight.shape[0]),
        n=int(up_weight.shape[1]),
        k=hidden,
        weight_scale_layout=weight_scale_layout,
    )

    _invoke_aot(
        _warpgemv_family,
        WarpGemvVariant(
            kind="up",
            hidden_size=hidden,
            intermediate_size=intermediate,
            top_k=top_k,
            warps_per_block=int(warps_per_block),
            weight_scale_layout=weight_scale_layout,
        ),
        [x, topk_ids, up_weight, up_scale, out],
    )


def _invoke_cute_moe_warpgemv_down_slots_fp8(
    activation: torch.Tensor,
    topk_ids: torch.Tensor,
    topk_weights: torch.Tensor,
    down_weight: torch.Tensor,
    down_scale: torch.Tensor,
    out: torch.Tensor,
    *,
    warps_per_block: int,
    weight_scale_layout: str = "channel",
) -> None:
    top_k = int(topk_ids.shape[1])
    hidden = int(down_weight.shape[1])
    intermediate = int(activation.shape[1])
    weight_scale_layout = _validate_fp8_scale_layout(weight_scale_layout)
    if weight_scale_layout == "block128_interleaved8":
        raise ValueError("down_slots does not support block128_interleaved8 scales")
    _validate_fp8_weight_scale_shape(
        down_scale,
        name="down_scale",
        num_experts=int(down_weight.shape[0]),
        n=hidden,
        k=intermediate,
        weight_scale_layout=weight_scale_layout,
    )

    _invoke_aot(
        _warpgemv_family,
        WarpGemvVariant(
            kind="down_slots",
            hidden_size=hidden,
            intermediate_size=intermediate,
            top_k=top_k,
            warps_per_block=int(warps_per_block),
            weight_scale_layout=weight_scale_layout,
            topk_weight_dtype=(
                "fp32" if topk_weights.dtype == torch.float32 else "bf16"
            ),
        ),
        [activation, topk_ids, topk_weights, down_weight, down_scale, out],
    )


def invoke_cute_moe(
    x: torch.Tensor,
    topk_ids: torch.Tensor,
    topk_weights: torch.Tensor,
    up_weight: torch.Tensor,
    up_scale: torch.Tensor,
    down_weight: torch.Tensor,
    down_scale: torch.Tensor,
    *,
    config: CuteMoeConfig,
    out: torch.Tensor | None = None,
    activation_scratch: torch.Tensor | None = None,
    weight_scale_layout: str = "channel",
    activation: str = "gelu",
) -> torch.Tensor:
    """Run a full CuTe MoE layer for non-routed kernel variants."""
    if config.kernel_type == "warpgemv":
        return _invoke_cute_moe_warpgemv(
            x,
            topk_ids,
            topk_weights,
            up_weight,
            up_scale,
            down_weight,
            down_scale,
            out=out,
            activation_scratch=activation_scratch,
            warps_per_block=config.num_warps,
            weight_dtype=config.dtype,
            weight_scale_layout=weight_scale_layout,
            activation=activation,
        )
    raise ValueError(
        f"invoke_cute_moe does not support kernel_type={config.kernel_type!r}"
    )


def _invoke_cute_moe_impl(
    kind: str,
    A: torch.Tensor,
    B: torch.Tensor,
    C: torch.Tensor,
    *,
    topk_weights: torch.Tensor | None,
    sorted_token_ids: torch.Tensor,
    expert_ids: torch.Tensor,
    num_tokens_post_padded: torch.Tensor,
    mul_routed_weight: bool,
    top_k: int,
    config: CuteMoeConfig,
) -> None:
    _require_routed_config(config)
    if A.dtype != torch.bfloat16:
        raise ValueError(f"CuTe fused MoE supports bfloat16 only (got {A.dtype})")
    if not (A.is_cuda and B.is_cuda and C.is_cuda):
        raise ValueError("A/B/C must be CUDA tensors")
    if A.ndim != 2:
        raise ValueError("A must be 2D")
    if B.ndim != 3:
        raise ValueError("B must be 3D [E, N, K]")
    if C.ndim != 3:
        raise ValueError("C must be 3D [M, top_k, N]")
    if B.stride(-1) != 1 or C.stride(-1) != 1:
        raise ValueError("B and C must be contiguous in their last dimension")
    if B.shape[2] != A.shape[1]:
        raise ValueError("A and B must have the same K dimension")
    _require_bf16_warp_full_n(config, int(B.shape[1]))
    if sorted_token_ids.dtype != torch.int32 or expert_ids.dtype != torch.int32:
        raise ValueError("sorted_token_ids and expert_ids must be int32")
    if num_tokens_post_padded.dtype != torch.int32:
        raise ValueError("num_tokens_post_padded must be int32")
    if mul_routed_weight:
        if topk_weights is None:
            raise ValueError("topk_weights is required when mul_routed_weight=True")
        topk_weights = _bf16_routed_weights(topk_weights)
    else:
        topk_weights = torch.empty((0,), device=A.device, dtype=A.dtype)

    C2d = C.view(-1, C.shape[-1])
    num_valid_tokens = int(A.shape[0]) * int(top_k)
    sorted_token_ids, expert_ids = _shrink_routing_for_em_launch(
        config, top_k, num_valid_tokens, sorted_token_ids, expert_ids,
    )

    variant, bundle = _variant_and_bundle(
        kind, config, int(B.shape[1]), int(A.shape[1]), use_pdl=False,
    )

    # Memref order matches the kernel class's `__call__` signature:
    # (mA, mB, mC, mTopkWeights, mSortedTokenIds, mExpertIds, mNumTokensPostPadded).
    _invoke_aot(
        _family,
        variant,
        [A, B, C2d, topk_weights,
         sorted_token_ids, expert_ids, num_tokens_post_padded],
        A,
         bundle=bundle,
    )


def _bf16_routed_weights(topk_weights: torch.Tensor) -> torch.Tensor:
    if topk_weights.dtype not in (torch.bfloat16, torch.float32):
        raise ValueError("BF16 routed MoE topk_weights must be bfloat16 or float32")
    # Model routers produce FP32 probabilities, so FP32 is the routed AOT ABI.
    # BF16 direct callers are normalized here; serving returns the input as-is.
    return topk_weights if topk_weights.dtype == torch.float32 else topk_weights.float()


def _validate_fp8_tensors(
    A_fp8_bits: torch.Tensor,
    A_scale: torch.Tensor,
    B_fp8_bits: torch.Tensor,
    B_scale: torch.Tensor,
    C: torch.Tensor,
    config: CuteMoeConfig,
    *,
    weight_scale_layout: str = "channel",
) -> tuple[torch.Tensor, torch.Tensor]:
    weight_scale_layout = _validate_fp8_scale_layout(weight_scale_layout)
    if A_fp8_bits.dtype != torch.uint8:
        raise ValueError(f"Expected FP8 activation bits as uint8 (got {A_fp8_bits.dtype})")
    if B_fp8_bits.dtype != torch.uint8:
        raise ValueError(f"Expected FP8 weight bits as uint8 (got {B_fp8_bits.dtype})")
    if A_scale.dtype not in (torch.float16, torch.float32):
        raise ValueError(f"Expected A_scale float16/float32 (got {A_scale.dtype})")
    if B_scale.dtype not in (torch.float16, torch.float32):
        raise ValueError(f"Expected B_scale float16/float32 (got {B_scale.dtype})")
    if C.dtype != torch.bfloat16:
        raise ValueError(f"CuTe MoE FP8 expects bfloat16 C (got {C.dtype})")
    if not (
        A_fp8_bits.is_cuda and A_scale.is_cuda
        and B_fp8_bits.is_cuda and B_scale.is_cuda and C.is_cuda
    ):
        raise ValueError("FP8 inputs must be CUDA tensors")
    if A_fp8_bits.ndim != 2 or A_scale.ndim != 1:
        raise ValueError("A_fp8_bits must be 2D and A_scale must be 1D")
    if B_fp8_bits.ndim != 3:
        raise ValueError("B_fp8_bits must be 3D [E, N, K]")
    if weight_scale_layout == "channel" and B_scale.ndim != 2:
        raise ValueError("channel B_scale must be 2D [E, N]")
    if weight_scale_layout == "block128" and B_scale.ndim != 3:
        raise ValueError("block128 B_scale must be 3D [E, ceil(N / 128), ceil(K / 128)]")
    if weight_scale_layout == "block128_interleaved8" and B_scale.ndim != 4:
        raise ValueError(
            "block128_interleaved8 B_scale must be 4D "
            "[E, 2, ceil((N / 2) / 128), ceil(K / 128)]"
        )
    if C.ndim != 3:
        raise ValueError("C must be 3D [M, top_k, N]")
    if A_fp8_bits.stride(-1) != 1 or B_fp8_bits.stride(-1) != 1 or C.stride(-1) != 1:
        raise ValueError("A_fp8_bits, B_fp8_bits and C must be contiguous in the last dim")
    if A_scale.shape[0] != A_fp8_bits.shape[0]:
        raise ValueError("A_scale must have length matching A_fp8_bits.shape[0]")
    if B_fp8_bits.shape[2] != A_fp8_bits.shape[1]:
        raise ValueError("A_fp8_bits and B_fp8_bits must have the same K dimension")
    if int(A_fp8_bits.shape[1]) % int(config.block_k) != 0:
        raise ValueError("CuTe FP8 kernel requires K divisible by block_k")
    _validate_fp8_weight_scale_shape(
        B_scale,
        name="B_scale",
        num_experts=int(B_fp8_bits.shape[0]),
        n=int(B_fp8_bits.shape[1]),
        k=int(B_fp8_bits.shape[2]),
        weight_scale_layout=weight_scale_layout,
    )
    if B_scale.stride(-1) != 1:
        raise ValueError("B_scale must be contiguous in its last dimension")
    if A_scale.dtype != torch.float32:
        A_scale = A_scale.to(dtype=torch.float32)
    if B_scale.dtype != torch.float32:
        B_scale = B_scale.to(dtype=torch.float32)
    return A_scale, B_scale


def _invoke_cute_moe_fp8_impl(
    kind: str,
    A_fp8_bits: torch.Tensor,
    A_scale: torch.Tensor,
    B_fp8_bits: torch.Tensor,
    B_scale: torch.Tensor,
    C: torch.Tensor,
    *,
    topk_weights: torch.Tensor | None,
    sorted_token_ids: torch.Tensor,
    expert_ids: torch.Tensor,
    num_tokens_post_padded: torch.Tensor,
    mul_routed_weight: bool,
    top_k: int,
    config: CuteMoeConfig,
    use_pdl: bool = False,
    compact_schedule: bool = False,
    weight_scale_layout: str = "channel",
) -> None:
    _require_routed_config(config)
    A_scale, B_scale = _validate_fp8_tensors(
        A_fp8_bits,
        A_scale,
        B_fp8_bits,
        B_scale,
        C,
        config,
        weight_scale_layout=weight_scale_layout,
    )
    if sorted_token_ids.dtype != torch.int32 or expert_ids.dtype != torch.int32:
        raise ValueError("sorted_token_ids and expert_ids must be int32")
    if num_tokens_post_padded.dtype != torch.int32:
        raise ValueError("num_tokens_post_padded must be int32")
    if mul_routed_weight:
        if topk_weights is None:
            raise ValueError("topk_weights is required when mul_routed_weight=True")
    else:
        topk_weights = torch.empty((0,), device=C.device, dtype=C.dtype)

    arch = get_cuda_arch()

    if config.kernel_type == "wgmma" and not sm_arch_at_least(arch, 90):
        raise ValueError(f"FP8 WGMMA kernels require SM90+ (got arch={arch})")
    if use_pdl and not sm_arch_at_least(arch, 90):
        raise ValueError(f"FP8 PDL kernels require SM90+ (got arch={arch})")

    C2d = C.view(-1, C.shape[-1])
    if config.kernel_type == "wgmma" and not compact_schedule:
        num_valid_tokens = int(A_fp8_bits.shape[0]) * int(top_k)
        sorted_token_ids, expert_ids = _shrink_routing_for_em_launch(
            config, top_k, num_valid_tokens, sorted_token_ids, expert_ids,
        )

    variant, bundle = _variant_and_bundle(
        kind,
        config,
        int(C2d.shape[1]),
        int(A_fp8_bits.shape[1]),
        use_pdl=use_pdl,
        compact_schedule=compact_schedule,
        weight_scale_layout=weight_scale_layout,
    )

    # Memref order matches the fp8 kernel's `__call__` signature. For compact
    # warp/qmma/wgmma, `num_tokens_post_padded` is the block-offset tensor:
    # [0] = active block count, [1:] = row boundaries.
    _invoke_aot(
        _family,
        variant,
        [A_fp8_bits, A_scale, B_fp8_bits, B_scale, C2d, topk_weights,
         sorted_token_ids, expert_ids, num_tokens_post_padded],
        A_fp8_bits,
        bundle=bundle,
    )


def _invoke_cute_moe_fp8_tcgen_impl(
    kind: str,
    A_fp8_bits: torch.Tensor,
    A_scale: torch.Tensor,
    B_fp8_bits: torch.Tensor,
    B_scale: torch.Tensor,
    C: torch.Tensor,
    *,
    topk_weights: torch.Tensor | None,
    sorted_token_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    A_routed_bits: torch.Tensor,
    row_scale: torch.Tensor,
    mul_routed_weight: bool,
    top_k: int,
    config: CuteMoeConfig,
) -> None:
    _require_tcgen_config(config)
    A_scale, B_scale = _validate_fp8_tensors(
        A_fp8_bits, A_scale, B_fp8_bits, B_scale, C, config,
    )
    if sorted_token_ids.dtype != torch.int32:
        raise ValueError("sorted_token_ids must be int32")
    if (
        cu_seqlens_m.dtype != torch.int32
        or cu_seqlens_m.ndim != 1
        or not cu_seqlens_m.is_contiguous()
    ):
        raise ValueError("cu_seqlens_m must be a contiguous int32 1D tensor")
    if A_routed_bits.dtype != torch.uint8 or row_scale.dtype != torch.float32:
        raise ValueError("A_routed_bits must be uint8 and row_scale must be fp32")
    if mul_routed_weight:
        if topk_weights is None:
            raise ValueError("topk_weights is required when mul_routed_weight=True")
    else:
        topk_weights = torch.empty((0,), device=C.device, dtype=C.dtype)

    arch = get_cuda_arch()
    if not sm_arch_at_least(arch, 100):
        raise ValueError(f"FP8 tcgen kernels require SM100+ (got arch={arch})")

    C2d = C.view(-1, C.shape[-1])
    variant, bundle = _variant_and_bundle(
        kind, config, int(C2d.shape[1]), int(A_fp8_bits.shape[1]), use_pdl=False,
    )
    from kestrel_kernels.cute_moe._tcgen_routing import (
        materialize_tcgen_dispatch_tensors,
    )

    tcgen_tensors = materialize_tcgen_dispatch_tensors(
        kind,
        A_fp8_bits,
        A_scale,
        B_fp8_bits,
        B_scale,
        C2d,
        sorted_token_ids=sorted_token_ids,
        cu_seqlens_m=cu_seqlens_m,
        A_routed_bits=A_routed_bits,
        row_scale=row_scale,
        topk_weights=topk_weights if mul_routed_weight else None,
        mul_routed_weight=mul_routed_weight,
        top_k=top_k,
        num_experts=int(B_fp8_bits.shape[0]),
    )
    _invoke_aot(_family, variant, tcgen_tensors, A_fp8_bits, bundle=bundle)


def _invoke_cute_moe_bf16_tcgen_impl(
    kind: str,
    A_routed: torch.Tensor,
    B: torch.Tensor,
    C: torch.Tensor,
    *,
    sorted_token_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    row_scale: torch.Tensor,
    config: CuteMoeConfig,
) -> None:
    _require_tcgen_config(config)
    if config.dtype != "bf16":
        raise ValueError("BF16 tcgen MoE requires dtype='bf16'")
    if A_routed.dtype != torch.bfloat16 or B.dtype != torch.bfloat16:
        raise ValueError("BF16 tcgen MoE requires BF16 operands")
    if C.dtype != torch.bfloat16:
        raise ValueError("BF16 tcgen MoE requires BF16 output")
    if A_routed.ndim != 2 or B.ndim != 3 or C.ndim not in (2, 3):
        raise ValueError("BF16 tcgen MoE expects A [routed,K], B [E,N,K], C [*,N]")
    if not A_routed.is_contiguous() or B.stride(-1) != 1 or not C.is_contiguous():
        raise ValueError("BF16 tcgen A/C must be contiguous and B must be contiguous in K")
    if sorted_token_ids.dtype != torch.int32 or not sorted_token_ids.is_contiguous():
        raise ValueError("sorted_token_ids must be contiguous int32")
    if (
        cu_seqlens_m.dtype != torch.int32
        or cu_seqlens_m.ndim != 1
        or not cu_seqlens_m.is_contiguous()
    ):
        raise ValueError("cu_seqlens_m must be contiguous int32")
    if row_scale.dtype != torch.float32 or not row_scale.is_contiguous():
        raise ValueError("row_scale must be contiguous fp32")
    route_rows, K = map(int, A_routed.shape)
    num_experts, N, B_K = map(int, B.shape)
    if route_rows != sorted_token_ids.numel() or route_rows != row_scale.numel():
        raise ValueError("A_routed, sorted_token_ids, and row_scale must have equal rows")
    if B_K != K or int(C.shape[-1]) != N:
        raise ValueError("BF16 tcgen operand K and output N dimensions must match")
    # Tried block_n=256 for Gemma's N=1408 up projection: 4.5% mismatched
    # elements (max 5.125), with some schedules faulting; require full N tiles.
    if N % int(config.block_n) != 0:
        raise ValueError("BF16 tcgen output N must be divisible by block_n")
    if cu_seqlens_m.numel() != num_experts + 1:
        raise ValueError("cu_seqlens_m must have shape [num_experts + 1]")
    arch = get_cuda_arch()
    if not (arch.startswith("sm100") or arch.startswith("sm110")):
        raise ValueError(f"BF16 tcgen MoE requires SM100/SM110 (got arch={arch})")

    C2d = C.view(-1, C.shape[-1])
    variant, bundle = _variant_and_bundle(
        kind, config, N, K, use_pdl=config.use_pdl,
    )
    bscale_dummy = torch.empty((0, N), device=C.device, dtype=torch.float32)
    tensors = [
        A_routed,
        B.permute(1, 2, 0),
        C2d,
        sorted_token_ids,
        row_scale,
        bscale_dummy,
        cu_seqlens_m,
    ]
    _invoke_aot(_family, variant, tensors, A_routed, bundle=bundle)


def invoke_lora_expand_tcgen(
    A_sorted: torch.Tensor,    # (M_total, rank_bucket) bf16 — sorted shrink scratch
    lora_b: torch.Tensor,      # (loras * E, N, rank_storage) bf16
    C2d: torch.Tensor,         # (num_assignments, N) bf16 — accumulate target
    aid_per_row: torch.Tensor, # (M_total,) int32 — sorted assignment ids
    row_scale: torch.Tensor,   # (M_total,) fp32 — 1.0 (up) / routed weight (down)
    cu_seqlens: torch.Tensor,  # (loras * E + 1,) int32 — adapter-weight key offsets
) -> None:
    """BF16 LoRA expand as a TCGen05 varlen grouped GEMM (SM100 only)."""
    arch = get_cuda_arch()
    # Datacenter Blackwell only — the lora_expand variants ship for
    # sm_100/sm_110 and consumer sm_120 has no tcgen05.
    if not (arch.startswith("sm100") or arch.startswith("sm110")):
        raise ValueError(
            f"LoRA tcgen expand requires sm_100/sm_110 (got arch={arch})"
        )
    if A_sorted.dtype != torch.bfloat16 or lora_b.dtype != torch.bfloat16:
        raise ValueError("LoRA tcgen expand expects bf16 operands")
    if C2d.dtype != torch.bfloat16:
        raise ValueError("LoRA tcgen expand expects bf16 C")
    if int(lora_b.shape[2]) != int(A_sorted.shape[1]):
        raise ValueError(
            "LoRA tcgen expand requires lora_b storage rank == scratch rank bucket"
        )
    variant = MoeVariant(
        kind="lora_expand",
        block_m=128,
        block_n=128,
        block_k=64,
        num_warps=4,
        num_stages=2,
        N=int(C2d.shape[1]),
        K=int(A_sorted.shape[1]),
        dtype="bf16",
        kernel_type="tcgen",
    )
    B_perm = lora_b.permute(1, 2, 0)
    bscale_dummy = torch.empty(
        (0, int(C2d.shape[1])), device=C2d.device, dtype=torch.float32
    )
    tensors = [A_sorted, B_perm, C2d, aid_per_row, row_scale, bscale_dummy, cu_seqlens]
    _invoke_aot(_family, variant, tensors, A_sorted)


def _invoke_cute_moe_down_activated_tcgen_impl(
    base_up: torch.Tensor,
    activation: torch.Tensor,
    B_fp8_bits: torch.Tensor,
    B_scale: torch.Tensor,
    C: torch.Tensor,
    *,
    topk_weights: torch.Tensor,
    sorted_token_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    A_routed_bits: torch.Tensor,
    row_scale: torch.Tensor,
    config: CuteMoeConfig,
) -> None:
    _require_tcgen_config(config)
    if base_up.dtype != torch.bfloat16 or activation.dtype != torch.bfloat16:
        raise ValueError("tcgen activated down invoke expects bf16 base_up and activation")
    if C.dtype != torch.bfloat16:
        raise ValueError("tcgen activated down invoke expects bf16 C")
    if B_fp8_bits.dtype != torch.uint8:
        raise ValueError(f"Expected FP8 weight bits as uint8 (got {B_fp8_bits.dtype})")
    if B_scale.dtype not in (torch.float16, torch.float32):
        raise ValueError(f"Expected B_scale float16/float32 (got {B_scale.dtype})")
    if not (
        base_up.is_cuda
        and activation.is_cuda
        and B_fp8_bits.is_cuda
        and B_scale.is_cuda
        and C.is_cuda
    ):
        raise ValueError("tcgen activated down inputs must be CUDA tensors")
    if base_up.ndim != 3 or activation.ndim != 2 or B_fp8_bits.ndim != 3 or C.ndim != 3:
        raise ValueError("invalid tcgen activated down tensor rank")
    if (
        base_up.stride(-1) != 1
        or activation.stride(-1) != 1
        or B_fp8_bits.stride(-1) != 1
        or C.stride(-1) != 1
    ):
        raise ValueError("base_up, activation, B_fp8_bits and C must be contiguous in last dim")
    if not base_up.is_contiguous() or not activation.is_contiguous():
        raise ValueError("base_up and activation must be contiguous")
    assignments = int(base_up.shape[0]) * int(base_up.shape[1])
    intermediate = int(activation.shape[1])
    if tuple(activation.shape) != (assignments, int(base_up.shape[2]) // 2):
        raise ValueError("activation must have shape [tokens * top_k, intermediate]")
    if int(base_up.shape[2]) != 2 * intermediate:
        raise ValueError("base_up must have shape [tokens, top_k, 2 * intermediate]")
    if B_fp8_bits.shape[2] != intermediate:
        raise ValueError("activation and B_fp8_bits must have the same K dimension")
    if intermediate not in (1024, 2048):
        raise ValueError("tcgen activated down supports K in {1024, 2048}")
    if int(intermediate) % int(config.block_k) != 0:
        raise ValueError("tcgen activated down requires K divisible by block_k")
    if B_scale.shape[0] != B_fp8_bits.shape[0] or B_scale.shape[1] != B_fp8_bits.shape[1]:
        raise ValueError("B_scale must have shape [E, N] matching B_fp8_bits")
    if B_scale.stride(-1) != 1:
        raise ValueError("B_scale must be contiguous in its last dimension")
    if (
        topk_weights.device != base_up.device
        or sorted_token_ids.device != base_up.device
        or cu_seqlens_m.device != base_up.device
        or A_routed_bits.device != base_up.device
        or row_scale.device != base_up.device
    ):
        raise ValueError("tcgen activated down route tensors must be on the input device")
    if (
        topk_weights.dtype not in (torch.bfloat16, torch.float32)
        or topk_weights.ndim != 1
        or not topk_weights.is_contiguous()
        or topk_weights.numel() < assignments
    ):
        raise ValueError("topk_weights must be contiguous bf16/fp32 with length >= assignments")
    if (
        sorted_token_ids.dtype != torch.int32
        or sorted_token_ids.ndim != 1
        or not sorted_token_ids.is_contiguous()
        or sorted_token_ids.numel() != assignments
    ):
        raise ValueError("sorted_token_ids must be contiguous int32 with length assignments")
    if (
        cu_seqlens_m.dtype != torch.int32
        or cu_seqlens_m.ndim != 1
        or cu_seqlens_m.numel() != int(B_fp8_bits.shape[0]) + 1
        or not cu_seqlens_m.is_contiguous()
    ):
        raise ValueError("cu_seqlens_m must be contiguous int32 with shape [num_experts + 1]")
    if (
        A_routed_bits.dtype != torch.uint8
        or A_routed_bits.ndim != 2
        or A_routed_bits.shape[0] < assignments
        or A_routed_bits.shape[1] != intermediate
        or not A_routed_bits.is_contiguous()
    ):
        raise ValueError("A_routed_bits must be contiguous uint8 [assignments, intermediate]")
    if (
        row_scale.dtype != torch.float32
        or row_scale.ndim != 1
        or row_scale.numel() < assignments
        or not row_scale.is_contiguous()
    ):
        raise ValueError("row_scale must be contiguous fp32 with length >= assignments")
    if B_scale.dtype != torch.float32:
        B_scale = B_scale.to(dtype=torch.float32)

    arch = get_cuda_arch()
    if not sm_arch_at_least(arch, 100):
        raise ValueError(f"FP8 tcgen kernels require SM100+ (got arch={arch})")

    C2d = C.view(-1, C.shape[-1])
    variant, bundle = _variant_and_bundle(
        "down", config, int(C2d.shape[1]), intermediate, use_pdl=False,
    )
    from kestrel_kernels.cute_moe._tcgen_routing import (
        materialize_tcgen_dispatch_tensors_from_base_up,
    )

    tcgen_tensors = materialize_tcgen_dispatch_tensors_from_base_up(
        base_up.view(assignments, int(base_up.shape[2])),
        B_fp8_bits,
        B_scale,
        C2d,
        sorted_token_ids=sorted_token_ids,
        cu_seqlens_m=cu_seqlens_m,
        A_routed_bits=A_routed_bits,
        row_scale=row_scale,
        activation=activation,
        topk_weights=topk_weights,
        num_experts=int(B_fp8_bits.shape[0]),
    )
    _invoke_aot(_family, variant, tcgen_tensors, base_up, bundle=bundle)


def _mxfp8_tensor(tensor: torch.Tensor, name: str) -> torch.Tensor:
    if tensor.dtype == torch.float8_e4m3fn:
        return tensor
    if tensor.dtype == torch.uint8:
        return tensor.view(torch.float8_e4m3fn)
    raise ValueError(f"{name} must be torch.float8_e4m3fn or uint8 storage")


def _mxfp4_tensor(tensor: torch.Tensor, name: str) -> torch.Tensor:
    fp4_dtype = getattr(torch, "float4_e2m1fn_x2", None)
    if fp4_dtype is not None and tensor.dtype == fp4_dtype:
        return tensor
    if tensor.dtype in (torch.uint8, torch.int8):
        if fp4_dtype is None:
            return tensor
        return tensor.view(fp4_dtype)
    raise ValueError(f"{name} must be torch.float4_e2m1fn_x2 or byte storage")


def _e8m0_scale_tensor(tensor: torch.Tensor, name: str) -> torch.Tensor:
    e8m0_dtype = getattr(torch, "float8_e8m0fnu", None)
    if e8m0_dtype is not None and tensor.dtype == e8m0_dtype:
        return tensor
    if tensor.dtype == torch.uint8:
        if e8m0_dtype is None:
            return tensor
        return tensor.view(e8m0_dtype)
    raise ValueError(f"{name} must be torch.float8_e8m0fnu or uint8 storage")


def _invoke_cute_moe_mxfp4_tcgen_impl(
    kind: str,
    A_mxfp8: torch.Tensor,
    B_mxfp4: torch.Tensor,
    C: torch.Tensor,
    *,
    sorted_token_ids: torch.Tensor,
    A_idx: torch.Tensor | None,
    block_offsets: torch.Tensor,
    block_expert_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    row_scale: torch.Tensor,
    A_block_scale: torch.Tensor,
    B_block_scale: torch.Tensor,
    config: CuteMoeConfig,
) -> None:
    _require_mxfp4_tcgen_config(config)
    A_mxfp8 = _mxfp8_tensor(A_mxfp8, "A_mxfp8")
    B_mxfp4 = _mxfp4_tensor(B_mxfp4, "B_mxfp4")
    A_block_scale = _e8m0_scale_tensor(A_block_scale, "A_block_scale")
    B_block_scale = _e8m0_scale_tensor(B_block_scale, "B_block_scale")

    if A_mxfp8.device.type != "cuda":
        raise ValueError("MXFP4 tcgen MoE requires CUDA tensors")
    if not (
        B_mxfp4.device == A_mxfp8.device
        and C.device == A_mxfp8.device
        and sorted_token_ids.device == A_mxfp8.device
        and block_offsets.device == A_mxfp8.device
        and block_expert_ids.device == A_mxfp8.device
        and cu_seqlens_m.device == A_mxfp8.device
        and row_scale.device == A_mxfp8.device
        and A_block_scale.device == A_mxfp8.device
        and B_block_scale.device == A_mxfp8.device
    ):
        raise ValueError("MXFP4 tcgen MoE inputs must be on one CUDA device")
    if C.dtype != torch.bfloat16:
        raise ValueError("MXFP4 tcgen MoE output must be BF16")
    if A_mxfp8.ndim != 2 or B_mxfp4.ndim != 3 or C.ndim not in (2, 3):
        raise ValueError("MXFP4 tcgen MoE expects A [M,K], B [E,N,K/2], C [*,N]")
    if not A_mxfp8.is_contiguous() or not C.is_contiguous():
        raise ValueError("A_mxfp8 and C must be contiguous")
    if B_mxfp4.stride(-1) != 1:
        raise ValueError("B_mxfp4 must be contiguous in K")
    if sorted_token_ids.dtype != torch.int32 or not sorted_token_ids.is_contiguous():
        raise ValueError("sorted_token_ids must be contiguous int32")
    if block_offsets.dtype != torch.int32 or not block_offsets.is_contiguous():
        raise ValueError("block_offsets must be contiguous int32")
    if block_expert_ids.dtype != torch.int32 or not block_expert_ids.is_contiguous():
        raise ValueError("block_expert_ids must be contiguous int32")
    if cu_seqlens_m.dtype != torch.int32 or not cu_seqlens_m.is_contiguous():
        raise ValueError("cu_seqlens_m must be contiguous int32")
    if row_scale.dtype != torch.float32 or not row_scale.is_contiguous():
        raise ValueError("row_scale must be contiguous fp32")
    if A_block_scale.ndim != 4 or B_block_scale.ndim != 4:
        raise ValueError("A_block_scale and B_block_scale must be rank-4 E8M0 tensors")
    if A_block_scale.stride(-1) != 1 or B_block_scale.stride(-1) != 1:
        raise ValueError("A_block_scale and B_block_scale must be contiguous in the 512B atom")

    route_rows = int(sorted_token_ids.numel())
    K = int(A_mxfp8.shape[1])
    num_experts, N, B_K_packed = map(int, B_mxfp4.shape)
    if route_rows == 0:
        return
    if B_K_packed * 2 != K:
        raise ValueError("B_mxfp4 must store packed K/2 float4_e2m1 pairs")
    if C.shape[-1] != N:
        raise ValueError("C N dimension must match B_mxfp4")
    if row_scale.numel() < route_rows:
        raise ValueError("row_scale must cover every routed row")
    if block_offsets.ndim != 1 or block_expert_ids.ndim != 1:
        raise ValueError("block_offsets and block_expert_ids must be rank-1")
    if block_offsets.numel() < block_expert_ids.numel() + 2:
        raise ValueError("block_offsets must have capacity block_expert_ids + 2")
    if kind == "down" and int(A_mxfp8.shape[0]) != route_rows:
        raise ValueError("down MXFP4 tcgen expects one A row per routed row")
    if kind == "up":
        if (
            A_idx is None
            or A_idx.device != A_mxfp8.device
            or A_idx.dtype != torch.int32
            or A_idx.ndim != 1
            or A_idx.numel() != route_rows
            or not A_idx.is_contiguous()
        ):
            raise ValueError("up MXFP4 tcgen requires contiguous int32 A_idx per routed row")
    if cu_seqlens_m.numel() != num_experts + 1:
        raise ValueError("cu_seqlens_m must have shape [num_experts + 1]")
    k_scale_blocks = ceil_div(K, 128)
    n_scale_blocks = ceil_div(N, 128)
    if (
        int(A_block_scale.shape[0]) != 1
        or int(A_block_scale.shape[1]) < num_experts
        or int(A_block_scale.shape[2]) != k_scale_blocks
        or int(A_block_scale.shape[3]) != 512
    ):
        raise ValueError(
            "A_block_scale must have shape [1, padded_expert_m_tiles, ceil(K/128), 512] "
            "with at least one 128-row tile per expert"
        )
    if tuple(map(int, B_block_scale.shape)) != (
        num_experts,
        n_scale_blocks,
        k_scale_blocks,
        512,
    ):
        raise ValueError(
            "B_block_scale must have shape [experts, ceil(N/128), ceil(K/128), 512]"
        )

    arch = get_cuda_arch()
    if not sm_arch_at_least(arch, 100):
        raise ValueError(f"MXFP4 tcgen kernels require SM100+ (got arch={arch})")

    C2d = C.view(-1, C.shape[-1])
    variant, bundle = _variant_and_bundle(kind, config, N, K, use_pdl=False)
    tensors = [
        A_mxfp8,
        B_mxfp4.permute(1, 2, 0),
        C2d,
        sorted_token_ids,
        A_idx if kind == "up" else sorted_token_ids,
        block_offsets,
        block_expert_ids,
        row_scale,
        cu_seqlens_m,
        A_block_scale,
        B_block_scale,
    ]
    _invoke_aot(_family, variant, tensors, A_mxfp8, bundle=bundle)


def _invoke_cute_moe_mxfp4_warp_impl(
    kind: str,
    A_fp8_bits: torch.Tensor,
    A_scale: torch.Tensor,
    B_mxfp4: torch.Tensor,
    B_block_scale: torch.Tensor,
    C: torch.Tensor,
    *,
    topk_weights: torch.Tensor | None,
    sorted_token_ids: torch.Tensor,
    block_offsets: torch.Tensor,
    block_expert_ids: torch.Tensor,
    mul_routed_weight: bool,
    top_k: int,
    config: CuteMoeConfig,
) -> None:
    _require_mxfp4_warp_config(config)
    B_mxfp4 = _mxfp4_storage_as_uint8(B_mxfp4, "B_mxfp4")
    B_block_scale = _e8m0_storage_as_uint8(B_block_scale, "B_block_scale")

    if A_fp8_bits.device.type != "cuda":
        raise ValueError("MXFP4 warp MoE requires CUDA tensors")
    if not (
        A_scale.device == A_fp8_bits.device
        and B_mxfp4.device == A_fp8_bits.device
        and B_block_scale.device == A_fp8_bits.device
        and C.device == A_fp8_bits.device
        and sorted_token_ids.device == A_fp8_bits.device
        and block_offsets.device == A_fp8_bits.device
        and block_expert_ids.device == A_fp8_bits.device
    ):
        raise ValueError("MXFP4 warp MoE inputs must be on one CUDA device")
    if A_fp8_bits.dtype != torch.uint8:
        raise ValueError("MXFP4 warp MoE requires uint8 FP8 activation bits")
    if A_scale.dtype not in (torch.float16, torch.float32):
        raise ValueError("MXFP4 warp MoE requires float16/float32 activation scales")
    if C.dtype != torch.bfloat16:
        raise ValueError("MXFP4 warp MoE requires BF16 output")
    if A_fp8_bits.ndim != 2 or A_scale.ndim != 1 or B_mxfp4.ndim != 3 or C.ndim not in (2, 3):
        raise ValueError(
            "MXFP4 warp MoE expects A_bits [M,K], A_scale [M], B [E,N,K/2], C [*,N]"
        )
    if A_scale.shape[0] != A_fp8_bits.shape[0]:
        raise ValueError("A_scale must have length matching A_fp8_bits rows")
    if kind == "up" and (C.ndim != 3 or int(C.shape[1]) != _CUTE_TOP_K_UP_DECODE):
        raise ValueError("MXFP4 warp up currently supports top_k=8")
    expected_c_rows = int(A_fp8_bits.shape[0]) * int(top_k)
    c_rows = int(C.numel()) // int(C.shape[-1])
    if c_rows != expected_c_rows:
        raise ValueError("MXFP4 warp C must have the expected flattened row count")
    if not A_fp8_bits.is_contiguous() or not A_scale.is_contiguous() or not C.is_contiguous():
        raise ValueError("A_fp8_bits, A_scale and C must be contiguous")
    if B_mxfp4.dtype != torch.uint8 or not B_mxfp4.is_contiguous():
        raise ValueError("B_mxfp4 must be contiguous uint8 interleaved MXFP4 storage")
    if B_block_scale.dtype != torch.uint8 or not B_block_scale.is_contiguous():
        raise ValueError("B_block_scale must be contiguous uint8 SFB E8M0 scales")
    if sorted_token_ids.dtype != torch.int32 or not sorted_token_ids.is_contiguous():
        raise ValueError("sorted_token_ids must be contiguous int32")
    if block_offsets.dtype != torch.int32 or not block_offsets.is_contiguous():
        raise ValueError("block_offsets must be contiguous int32")
    if block_expert_ids.dtype != torch.int32 or not block_expert_ids.is_contiguous():
        raise ValueError("block_expert_ids must be contiguous int32")
    if block_offsets.ndim != 1 or block_expert_ids.ndim != 1:
        raise ValueError("block_offsets and block_expert_ids must be rank-1")
    if block_offsets.numel() < block_expert_ids.numel() + 2:
        raise ValueError("block_offsets must have capacity block_expert_ids + 2")

    if mul_routed_weight:
        if topk_weights is None:
            raise ValueError("MXFP4 down warp requires topk_weights")
        if topk_weights.device != A_fp8_bits.device:
            raise ValueError("topk_weights must be on the input CUDA device")
        if topk_weights.dtype != torch.bfloat16 or not topk_weights.is_contiguous():
            raise ValueError("topk_weights must be contiguous BF16")
    else:
        topk_weights = torch.empty((0,), dtype=torch.bfloat16, device=A_fp8_bits.device)
    if A_scale.dtype != torch.float32:
        A_scale = A_scale.to(dtype=torch.float32)

    K = int(A_fp8_bits.shape[1])
    N = int(C.shape[-1])
    num_experts, B_N, B_K_packed = map(int, B_mxfp4.shape)
    if B_N != N or B_K_packed * 2 != K:
        raise ValueError("B_mxfp4 must have shape [experts, N, K/2]")
    if C.shape[-1] != N:
        raise ValueError("C N dimension must match B_mxfp4")
    if N % int(config.block_n) != 0:
        raise ValueError("MXFP4 warp N must be divisible by block_n")
    if K % int(config.block_k) != 0:
        raise ValueError("MXFP4 warp K must be divisible by block_k")
    if int(config.block_k) % 128 != 0:
        raise ValueError("MXFP4 warp block_k must be divisible by 128")
    if K % 128 != 0:
        raise ValueError("MXFP4 warp K must be divisible by 128 for SFB scales")
    expected_scale_shape = (num_experts, ceil_div(N, 128), K // 128, 512)
    if tuple(map(int, B_block_scale.shape)) != expected_scale_shape:
        raise ValueError(
            "B_block_scale must have shape [experts, ceil(N/128), K/128, 512]"
        )

    C2d = C.view(-1, C.shape[-1])
    variant, bundle = _variant_and_bundle(kind, config, N, K, use_pdl=False)
    _invoke_aot(
        _family,
        variant,
        [
            A_fp8_bits,
            A_scale,
            B_mxfp4,
            B_block_scale,
            C2d,
            topk_weights,
            sorted_token_ids,
            block_expert_ids,
            block_offsets,
        ],
        A_fp8_bits,
         bundle=bundle,
    )


def invoke_cute_moe_up(
    A: torch.Tensor,
    B: torch.Tensor,
    C: torch.Tensor,
    *,
    sorted_token_ids: torch.Tensor,
    expert_ids: torch.Tensor,
    num_tokens_post_padded: torch.Tensor,
    config: CuteMoeConfig | None = None,
) -> None:
    """CuTe fused MoE up-projection (no routed-weight scaling)."""
    if config is None:
        config = get_cute_moe_routed_config(
            A.shape[0],
            num_experts=B.shape[0],
            hidden_size=A.shape[1],
            intermediate_size=B.shape[1] // 2,
        )["up"]
    _invoke_cute_moe_impl(
        "up", A, B, C,
        topk_weights=None,
        sorted_token_ids=sorted_token_ids,
        expert_ids=expert_ids,
        num_tokens_post_padded=num_tokens_post_padded,
        mul_routed_weight=False,
        top_k=_CUTE_TOP_K_UP_DECODE,
        config=config,
    )


def invoke_cute_moe_down(
    A: torch.Tensor,
    B: torch.Tensor,
    C: torch.Tensor,
    *,
    topk_weights: torch.Tensor,
    sorted_token_ids: torch.Tensor,
    expert_ids: torch.Tensor,
    num_tokens_post_padded: torch.Tensor,
    config: CuteMoeConfig | None = None,
) -> None:
    """CuTe fused MoE down-projection (includes routed-weight scaling)."""
    if config is None:
        config = get_cute_moe_routed_config(
            C.shape[0],
            num_experts=B.shape[0],
            hidden_size=B.shape[1],
            intermediate_size=B.shape[2],
        )["down"]
    _invoke_cute_moe_impl(
        "down", A, B, C,
        topk_weights=topk_weights,
        sorted_token_ids=sorted_token_ids,
        expert_ids=expert_ids,
        num_tokens_post_padded=num_tokens_post_padded,
        mul_routed_weight=True,
        top_k=1,
        config=config,
    )


def invoke_cute_moe_up_fp8(
    A_fp8_bits: torch.Tensor,
    A_scale: torch.Tensor,
    B_fp8_bits: torch.Tensor,
    B_scale: torch.Tensor,
    C: torch.Tensor,
    *,
    sorted_token_ids: torch.Tensor,
    expert_ids: torch.Tensor,
    num_tokens_post_padded: torch.Tensor,
    config: CuteMoeConfig | None = None,
    use_pdl: bool = False,
    weight_scale_layout: str = "channel",
) -> None:
    """CuTe fused MoE up-projection with FP8 activations + weights (W8A8).

    `use_pdl=True` enables Programmatic Dependent Launch — the kernel
    waits via `griddepcontrol_wait()` before loading A tiles, allowing
    overlap with a preceding producer (e.g., FP8 quantization). SM90+ only.
    """
    if config is None:
        config = get_cute_moe_routed_config(
            A_fp8_bits.shape[0],
            num_experts=B_fp8_bits.shape[0],
            hidden_size=A_fp8_bits.shape[1],
            intermediate_size=B_fp8_bits.shape[1] // 2,
            dtype="fp8",
        )["up"]
    if config.kernel_type in ("warp", "qmma"):
        raise ValueError(
            "FP8 warp/qmma MoE uses compact routing; use invoke_cute_moe_up_fp8_compact"
        )
    _invoke_cute_moe_fp8_impl(
        "up", A_fp8_bits, A_scale, B_fp8_bits, B_scale, C,
        topk_weights=None,
        sorted_token_ids=sorted_token_ids,
        expert_ids=expert_ids,
        num_tokens_post_padded=num_tokens_post_padded,
        mul_routed_weight=False,
        top_k=_CUTE_TOP_K_UP_DECODE,
        config=config,
        use_pdl=use_pdl,
        weight_scale_layout=weight_scale_layout,
    )


